import re
from decimal import Decimal

class InsufficientFunds(Exception):
    pass

_AMOUNT_RE = re.compile(r'[0-9]+(?:\.[0-9]{1,2})?')

def _to_decimal(amount, allow_zero):
    if not isinstance(amount, str):
        raise TypeError("amount must be a string")
    if not _AMOUNT_RE.fullmatch(amount):
        raise ValueError("amount format must be digits with optional .dd")
    value = Decimal(amount)
    if not allow_zero and value == 0:
        raise ValueError("deposit/withdraw amount must not be zero")
    return value

def _fmt(value):
    if value == 0:
        value = Decimal('0.00')
    return f'{value:.2f}'

class Ledger:
    def __init__(self, overdraft_limit='0.00'):
        self._overdraft_limit = _to_decimal(overdraft_limit, allow_zero=True)
        self._balance = Decimal('0.00')
        self._history = []

    def deposit(self, amount):
        value = _to_decimal(amount, allow_zero=False)
        self._balance += value
        self._history.append(('deposit', _fmt(value)))

    def withdraw(self, amount):
        value = _to_decimal(amount, allow_zero=False)
        new_balance = self._balance - value
        if new_balance < -self._overdraft_limit:
            raise InsufficientFunds("withdrawal would exceed overdraft limit")
        self._balance = new_balance
        self._history.append(('withdraw', _fmt(value)))
        if self._balance < 0:
            fee = Decimal('1.50')
            self._balance -= fee
            self._history.append(('fee', _fmt(fee)))

    def balance(self):
        return _fmt(self._balance)

    def history(self):
        return list(self._history)
