import heapq
from typing import List, Tuple, Any


def _is_int(x: Any) -> bool:
    return isinstance(x, int) and not isinstance(x, bool)


def _validate(k: Any, meetings: Any) -> List[Tuple[int, int]]:
    if not _is_int(k) or k < 1:
        raise ValueError("k must be an int (not bool) and >= 1")
    try:
        seq = list(meetings)
    except TypeError:
        raise ValueError("meetings must be an iterable of (start, end) pairs")
    for i, mtg in enumerate(seq):
        if not isinstance(mtg, (list, tuple)) or len(mtg) != 2:
            raise ValueError(f"meeting at index {i} must be a pair")
        start, end = mtg
        if not _is_int(start) or not _is_int(end):
            raise ValueError(f"meeting at index {i}: start and end must be ints (not bool)")
        if start >= end:
            raise ValueError(f"meeting at index {i}: start must be less than end")
    return seq


def _allocate(seq: List[Tuple[int, int]], k: int):
    n = len(seq)
    order = sorted(range(n), key=lambda i: (seq[i][0], i))
    available = list(range(k))
    heapq.heapify(available)
    busy: List[Tuple[int, int]] = []
    for idx in order:
        start, end = seq[idx]
        duration = end - start
        while busy and busy[0][0] <= start:
            _, room = heapq.heappop(busy)
            heapq.heappush(available, room)
        if available:
            room = heapq.heappop(available)
            actual_start = start
        else:
            release_time, room = heapq.heappop(busy)
            actual_start = release_time
        actual_end = actual_start + duration
        heapq.heappush(busy, (actual_end, room))
        yield idx, room, actual_start, actual_end


def assign_rooms(meetings, k):
    seq = _validate(k, meetings)
    n = len(seq)
    if n == 0:
        return []
    result = [None] * n
    for idx, room, actual_start, actual_end in _allocate(seq, k):
        result[idx] = (room, actual_start, actual_end)
    return result


def busiest_room(meetings, k):
    seq = _validate(k, meetings)
    n = len(seq)
    if n == 0:
        return 0
    counts = [0] * k
    for idx, room, actual_start, actual_end in _allocate(seq, k):
        counts[room] += 1
    best = 0
    for r in range(1, k):
        if counts[r] > counts[best]:
            best = r
    return best
