import heapq
from typing import Iterable


class CycleError(ValueError):
    def __init__(self, nodes: Iterable[str]):
        self.nodes = sorted(nodes)
        super().__init__(f"cycle detected; unplaceable nodes: {self.nodes}")


def _build_graph(nodes: Iterable[str], edges: Iterable[tuple[str, str]]):
    node_set: set[str] = set(nodes)
    edge_set: set[tuple[str, str]] = set()

    for before, after in edges:
        if before not in node_set:
            raise ValueError(f"unknown node: {before!r}")
        if after not in node_set:
            raise ValueError(f"unknown node: {after!r}")
        edge_set.add((before, after))

    adj: dict[str, list[str]] = {node: [] for node in node_set}
    indegree: dict[str, int] = {node: 0 for node in node_set}

    for before, after in edge_set:
        adj[before].append(after)
        indegree[after] += 1

    return node_set, adj, indegree


def topo_order(nodes: Iterable[str], edges: Iterable[tuple[str, str]]) -> list[str]:
    node_set, adj, indegree = _build_graph(nodes, edges)

    heap = [node for node, deg in indegree.items() if deg == 0]
    heapq.heapify(heap)

    result: list[str] = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for nxt in adj[node]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(heap, nxt)

    if len(result) != len(node_set):
        raise CycleError(node_set - set(result))

    return result


def layers(nodes: Iterable[str], edges: Iterable[tuple[str, str]]) -> list[list[str]]:
    node_set, adj, indegree = _build_graph(nodes, edges)

    remaining = set(node_set)
    zero = {node for node in node_set if indegree[node] == 0}
    result: list[list[str]] = []

    while zero:
        layer = sorted(zero)
        result.append(layer)
        next_zero: set[str] = set()

        for node in layer:
            remaining.remove(node)
            for nxt in adj[node]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    next_zero.add(nxt)

        zero = next_zero

    if remaining:
        raise CycleError(remaining)

    return result
