def _clean(intervals):
    out = []
    for iv in intervals:
        if len(iv) != 2:
            raise ValueError("Each interval must be a 2-item sequence")
        start, end = iv
        if start > end:
            raise ValueError("Interval start must not be greater than end")
        if start == end:
            continue
        out.append((start, end))
    return out


def merge(intervals):
    cleaned = _clean(intervals)
    cleaned.sort(key=lambda x: x[0])
    merged = []
    for s, e in cleaned:
        if merged and s <= merged[-1][1]:
            if e > merged[-1][1]:
                merged[-1] = (merged[-1][0], e)
        else:
            merged.append((s, e))
    return merged


def subtract(a, b):
    a_merged = merge(a)
    b_merged = merge(b)
    result = []
    j = 0
    n = len(b_merged)

    for s, e in a_merged:
        while j < n and b_merged[j][1] <= s:
            j += 1

        cur = s
        while j < n and b_merged[j][0] < e:
            bs, be = b_merged[j]
            if bs > cur:
                result.append((cur, bs))
            cur = max(cur, be)
            if cur >= e:
                break
            if be < e:
                j += 1
            else:
                break

        if cur < e:
            result.append((cur, e))

    return result


def total_length(intervals):
    return sum(e - s for s, e in merge(intervals))
