    _validate_prices(prices)
    n = len(prices)
    result = [0] * n
    stack = []
    last_none = -1
    for i, p in enumerate(prices):
        if p is None:
            last_none = i
            stack.clear()
            continue
        while stack and prices[stack[-1]] <= p:
            stack.pop()
        if stack:
            result[i] = i - stack[-1]
        else:
            result[i] = i - last_none
        stack.append(i)
    return result


def next_greater(prices):
    _validate_prices(prices)
    n = len(prices)
    result = [-1] * n
    stack = []
    for j, p in enumerate(prices):
        if p is None:
            stack.clear()
            continue
        while stack and prices[stack[-1]] < p:
            result[stack.pop()] = j
        stack.append(j)
    return result


def widest_span(prices):
    _validate_prices(prices)
    s = spans(prices)
    best_index = -1
    best_span = 0
    for i, span in enumerate(s):
        if span > best_span:
            best_span = span
            best_index = i
        elif span == best_span and best_span > 0 and i > best_index:
            best_index = i
    if best_span == 0:
