def _is_digits(s):
    return s and all('0' <= c <= '9' for c in s)


def expand_field(field, lo, hi):
    if not field:
        raise ValueError("invalid cron: empty field")

    values = set()
    for item in field.split(','):
        if not item:
            raise ValueError("invalid cron: empty item")

        step = 1
        base = item
        has_step = False

        if '/' in base:
            parts = base.split('/')
            if len(parts) != 2:
                raise ValueError("invalid cron: malformed step")
            base, step_str = parts
            if not _is_digits(step_str):
                raise ValueError("invalid cron: step must be a positive integer")
            step = int(step_str)
            if step == 0:
                raise ValueError("invalid cron: step cannot be zero")
            has_step = True

        if base == '*':
            start, end = lo, hi
        elif '-' in base:
            parts = base.split('-')
            if len(parts) != 2:
                raise ValueError("invalid cron: malformed range")
            a_str, b_str = parts
            if not _is_digits(a_str) or not _is_digits(b_str):
                raise ValueError("invalid cron: range bounds must be integers")
            start = int(a_str)
            end = int(b_str)
            if start > end:
                raise ValueError("invalid cron: range start greater than end")
        else:
            if not _is_digits(base):
                raise ValueError("invalid cron: malformed number")
            start = int(base)
            end = hi if has_step else start

        if start < lo or end > hi:
            raise ValueError("invalid cron: value out of range")

        for v in range(start, end + 1, step):
            values.add(v)

    return sorted(values)


def _parse_expr(expr):
    if not isinstance(expr, str):
        raise ValueError("invalid cron: expression must be a string")
    parts = expr.split()
    if len(parts) != 2:
        raise ValueError("invalid cron: expression must have exactly two fields")
    minute_field, hour_field = parts
    minutes = expand_field(minute_field, 0, 59)
    hours = expand_field(hour_field, 0, 23)
    return minutes, hours


def cron_matches(expr, hour, minute):
    minutes, hours = _parse_expr(expr)
    return hour in hours and minute in minutes


def next_match(expr, hour, minute):
    minutes, hours = _parse_expr(expr)
    for offset in range(1, 1441):
        total = minute + offset
        h = (hour + total // 60) % 24
        m = total % 60
        if h in hours and m in minutes:
            return (h, m)
    return (hour, minute)
