class Scheduler:
    def __init__(self):
        self._tasks = {}
        self._order = 0

    def add(self, name, priority, after=()):
        if name in self._tasks:
            raise ValueError(f"Task {name!r} already added")
        after_tuple = tuple(after)
        for dep in after_tuple:
            if dep not in self._tasks:
                raise KeyError(dep)
        self._tasks[name] = {
            "priority": priority,
            "after": after_tuple,
            "order": self._order,
            "status": "pending",
        }
        self._order += 1

    def next(self):
        chosen = None
        chosen_key = None
        for name, info in self._tasks.items():
            if info["status"] != "pending":
                continue
            if all(
                self._tasks[dep]["status"] == "completed" for dep in info["after"]
            ):
                key = (info["priority"], -info["order"])
                if chosen_key is None or key > chosen_key:
                    chosen = name
                    chosen_key = key
        if chosen is None:
            return None
        self._tasks[chosen]["status"] = "running"
        return chosen

    def complete(self, name):
        if name not in self._tasks:
            raise KeyError(name)
        if self._tasks[name]["status"] != "running":
            raise ValueError(f"Task {name!r} is not running")
        self._tasks[name]["status"] = "completed"

    def remaining(self):
        return sum(
            1 for info in self._tasks.values() if info["status"] != "completed"
        )
