from bisect import bisect_right

def _validate_intervals(intervals):
    for interval in intervals:
        if not isinstance(interval, (tuple, list)) or len(interval) != 3:
            raise TypeError("each interval must be a tuple/list of (start, end, weight)")
        start, end, weight = interval
        for value in (start, end, weight):
            if not isinstance(value, int) or isinstance(value, bool):
                raise TypeError("start, end, and weight must be int")
        if start >= end:
            raise ValueError("start must be less than end")

def best_schedule(intervals):
    _validate_intervals(intervals)
    n = len(intervals)
    if n == 0:
        return (0, 0)
    sorted_intervals = sorted(intervals, key=lambda x: x[1])
    ends = [iv[1] for iv in sorted_intervals]
    best_w = [0] * (n + 1)
    best_c = [0] * (n + 1)
    for i in range(1, n + 1):
        start, end, weight = sorted_intervals[i - 1]
        p = bisect_right(ends, start)
        cand_w = weight + best_w[p]
        cand_c = 1 + best_c[p]
        skip_w = best_w[i - 1]
        skip_c = best_c[i - 1]
        if cand_w > skip_w or (cand_w == skip_w and cand_c < skip_c):
            best_w[i] = cand_w
            best_c[i] = cand_c
        else:
            best_w[i] = skip_w
            best_c[i] = skip_c
    return (best_w[n], best_c[n])

def max_parallel(intervals):
    _validate_intervals(intervals)
    events = []
    for start, end, _ in intervals:
        events.append((start, 1))
        events.append((end, -1))
    events.sort()
    current = 0
    max_count = 0
    for _, delta in events:
        current += delta
        if current > max_count:
            max_count = current
    return max_count
