import heapq


class MedianTracker:
    __slots__ = (
        "_low",
        "_high",
        "_delayed",
        "_low_size",
        "_high_size",
        "_prefer_high",
        "_count",
    )

    def __init__(self, prefer_high=False):
        self._prefer_high = bool(prefer_high)
        self._low = []
        self._high = []
        self._delayed = {}
        self._low_size = 0
        self._high_size = 0
        self._count = {}

    @staticmethod
    def _require_int(x):
        if type(x) is not int:
            raise TypeError("only int values are allowed")

    def add(self, x):
        self._require_int(x)
        self._count[x] = self._count.get(x, 0) + 1

        if self._prefer_high:
            self._prune_high()
            if not self._high or x >= self._high[0]:
                heapq.heappush(self._high, x)
                self._high_size += 1
            else:
                heapq.heappush(self._low, -x)
                self._low_size += 1
        else:
            self._prune_low()
            if not self._low or x <= -self._low[0]:
                heapq.heappush(self._low, -x)
                self._low_size += 1
            else:
                heapq.heappush(self._high, x)
                self._high_size += 1

        self._rebalance()

    def remove(self, x):
        self._require_int(x)
        c = self._count.get(x, 0)
        if c == 0:
            raise ValueError("not present")
        if c == 1:
            del self._count[x]
        else:
            self._count[x] = c - 1

        self._prune_low()
        if self._low and x <= -self._low[0]:
            self._low_size -= 1
        else:
            self._high_size -= 1

        self._delayed[x] = self._delayed.get(x, 0) + 1
        self._rebalance()

    def median(self):
        if self._low_size + self._high_size == 0:
            raise LookupError("empty")

        if self._prefer_high:
            self._prune_high()
            return self._high[0]

        self._prune_low()
        return -self._low[0]

    def __len__(self):
        return self._low_size + self._high_size

    def _prune_low(self):
        while self._low:
            v = -self._low[0]
            c = self._delayed.get(v, 0)
            if c:
                heapq.heappop(self._low)
                if c == 1:
                    del self._delayed[v]
                else:
                    self._delayed[v] = c - 1
            else:
                break

    def _prune_high(self):
        while self._high:
            v = self._high[0]
            c = self._delayed.get(v, 0)
            if c:
                heapq.heappop(self._high)
                if c == 1:
                    del self._delayed[v]
                else:
                    self._delayed[v] = c - 1
            else:
                break

    def _rebalance(self):
        if self._prefer_high:
            while self._high_size < self._low_size:
                self._prune_low()
                v = -heapq.heappop(self._low)
                self._low_size -= 1
                heapq.heappush(self._high, v)
                self._high_size += 1

            while self._low_size < self._high_size - 1:
                self._prune_high()
                v = heapq.heappop(self._high)
                self._high_size -= 1
                heapq.heappush(self._low, -v)
                self._low_size += 1
        else:
            while self._low_size < self._high_size:
                self._prune_high()
                v = heapq.heappop(self._high)
                self._high_size -= 1
                heapq.heappush(self._low, -v)
                self._low_size += 1

            while self._high_size < self._low_size - 1:
                self._prune_low()
                v = -heapq.heappop(self._low)
                self._low_size -= 1
                heapq.heappush(self._high, v)
                self._high_size += 1
