import re

_KEY_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)*")

def render(template, values):
    n = len(template)
    out = []
    i = 0
    literal_start = 0
    while i < n:
        ch = template[i]
        if ch == "\\":
            if i > literal_start:
                out.append(template[literal_start:i])
            if i + 1 < n and template[i + 1] == "\\":
                out.append("\\")
                i += 2
            elif i + 2 < n and template[i + 1] == "{" and template[i + 2] == "{":
                out.append("{{")
                i += 3
            else:
                out.append("\\")
                i += 1
            literal_start = i
            continue
        if ch == "{" and i + 1 < n and template[i + 1] == "{":
            if i > literal_start:
                out.append(template[literal_start:i])
            start = i
            close = template.find("}}", i + 2)
            if close == -1:
                raise ValueError(f"unclosed placeholder at {start}")
            content = template[i + 2:close]
            pipe = content.find("|")
            if pipe == -1:
                key_part = content
                default_text = None
            else:
                key_part = content[:pipe]
                default_text = content[pipe + 1:]
            key = key_part.strip(" ")
            if not _KEY_RE.fullmatch(key):
                raise ValueError("bad key: " + key)
            current = values
            missing = False
            for segment in key.split("."):
                if not isinstance(current, dict) or segment not in current:
                    missing = True
                    break
                current = current[segment]
            if not missing and current is None:
                missing = True
            if missing:
                if default_text is None:
                    raise KeyError("missing: " + key)
                out.append(default_text.strip(" "))
            else:
                if current is True:
                    out.append("true")
                elif current is False:
                    out.append("false")
                else:
                    out.append(str(current))
            i = close + 2
            literal_start = i
            continue
        i += 1
    if literal_start < n:
        out.append(template[literal_start:n])
    return "".join(out)
