import re

__all__ = ["glob_to_regex", "glob_match"]

# Token kinds
_LIT = "LITERAL"
_STAR = "STAR"
_QUES = "QUESTION"
_SLASH = "SLASH"
_BROPEN = "BRACKET_OPEN"
_BRCLOSE = "BRACKET_CLOSE"
_START = "START"
_END = "END"

_CLASS_SPECIAL = set("]^-\\")


def _tokenize(pattern: str):
    tokens = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == "\\":
            if i + 1 < n:
                tokens.append((_LIT, pattern[i + 1]))
                i += 2
            else:
                tokens.append((_LIT, "\\"))
                i += 1
        elif c == "*":
            tokens.append((_STAR, "*"))
            i += 1
        elif c == "?":
            tokens.append((_QUES, "?"))
            i += 1
        elif c == "/":
            tokens.append((_SLASH, "/"))
            i += 1
        elif c == "[":
            tokens.append((_BROPEN, "["))
            i += 1
        elif c == "]":
            tokens.append((_BRCLOSE, "]"))
            i += 1
        else:
            tokens.append((_LIT, c))
            i += 1
    return tokens


def _class_escape(ch: str) -> str:
    if ch in _CLASS_SPECIAL:
        return "\\" + ch
    return ch


def _class_regex(members, negated: bool) -> str:
    if negated:
        parts = []
        for kind, value in members:
            if kind == "literal":
                parts.append(_class_escape(value))
            else:
                a, b = value
                parts.append(_class_escape(a) + "-" + _class_escape(b))
        return "[^/" + "".join(parts) + "]"

    intervals = []
    for kind, value in members:
        if kind == "literal":
            if value != "/":
                intervals.append((ord(value), ord(value)))
        else:
            a, b = value
            lo, hi = ord(a), ord(b)
            if lo > hi:
                continue
            slash = ord("/")
            if lo <= slash <= hi:
                if lo <= slash - 1:
                    intervals.append((lo, slash - 1))
                if slash + 1 <= hi:
                    intervals.append((slash + 1, hi))
            else:
                intervals.append((lo, hi))

    if not intervals:
        return "(?!)"

    intervals.sort()
    merged = []
    for s, e in intervals:
        if merged and s <= merged[-1][1] + 1:
            merged[-1] = (merged[-1][0], max(merged[-1][1], e))
        else:
            merged.append((s, e))

    parts = []
    for s, e in merged:
        if s == e:
            parts.append(_class_escape(chr(s)))
        else:
            parts.append(_class_escape(chr(s)) + "-" + _class_escape(chr(e)))
    return "[" + "".join(parts) + "]"


def _parse_class(tokens, i: int):
    n = len(tokens)
    j = i + 1
    negated = False
    if j < n and tokens[j][0] == _LIT and tokens[j][1] == "!":
        negated = True
        j += 1

    members = []

    if j < n and tokens[j][0] == _BRCLOSE:
        members.append(("literal", "]"))
        j += 1

    while j < n and tokens[j][0] != _BRCLOSE:
        kind, ch = tokens[j]
        if ch == "-" and members and (j + 1 < n) and tokens[j + 1][0] != _BRCLOSE:
            prev_kind, prev_val = members[-1]
            next_ch = tokens[j + 1][1]
            if (
                prev_kind == "literal"
                and len(prev_val) == 1
                and ord(prev_val) <= ord(next_ch)
            ):
                members[-1] = ("range", (prev_val, next_ch))
                j += 2
                continue
        members.append(("literal", ch))
        j += 1

    if j >= n:
        return re.escape("["), i + 1

    j += 1
    return _class_regex(members, negated), j


def glob_to_regex(pattern: str) -> str:
    tokens = _tokenize(pattern)
    n = len(tokens)
    i = 0
    parts = []

    while i < n:
        kind, ch = tokens[i]

        if kind == _LIT:
            parts.append(re.escape(ch))
            i += 1
        elif kind == _SLASH:
            parts.append("/")
            i += 1
        elif kind == _QUES:
            parts.append("[^/]")
            i += 1
        elif kind == _BROPEN:
            frag, i = _parse_class(tokens, i)
            parts.append(frag)
        elif kind == _BRCLOSE:
            parts.append(re.escape("]"))
            i += 1
        elif kind == _STAR:
            j = i
            while j < n and tokens[j][0] == _STAR:
                j += 1
            count = j - i
            prev_kind = tokens[i - 1][0] if i > 0 else _START
            next_kind = tokens[j][0] if j < n else _END

            if (
                count == 2
                and prev_kind in (_SLASH, _START)
                and next_kind in (_SLASH, _END)
            ):
                if next_kind == _SLASH:
                    parts.append("(?:[^/]+/)*")
                    i = j + 1
                else:
                    parts.append("(?s:.*)")
                    i = j
            else:
                parts.append("[^/]*")
                i = j
        else:
            parts.append(re.escape(ch))
            i += 1

    return "".join(parts)


def glob_match(pattern: str, path: str) -> bool:
    return re.fullmatch(glob_to_regex(pattern), path) is not None
