def fetch_with_retry(fetch, sleep, max_attempts=3, max_delay=30):
    """Call ``fetch`` up to ``max_attempts`` times, retrying only on ConnectionError.

    Sleeps between attempts using exponentially doubling delays, capped at
    ``max_delay``.  The last ConnectionError is re-raised unchanged after the
    final attempt.
    """
    if max_attempts < 1:
        raise ValueError("max_attempts must be at least 1")

    delay = 1
    last_error = None

    for attempt in range(max_attempts):
        try:
            return fetch()
        except ConnectionError as exc:
            last_error = exc
            if attempt < max_attempts - 1:
                sleep(min(delay, max_delay))
                delay *= 2

    if last_error is not None:
        raise last_error
