_OPERATORS = ('==', '!=', '>=', '<=', '~=', '>', '<')


def _parse_version(v):
    s = v.strip()
    if not s:
        raise ValueError(f"Invalid version: {v!r}")
    parts = s.split('.')
    nums = []
    for p in parts:
        if not p or not p.isdigit():
            raise ValueError(f"Invalid version: {v!r}")
        nums.append(int(p))
    return nums


def _compare(a, b):
    n = max(len(a), len(b))
    for i in range(n):
        av = a[i] if i < len(a) else 0
        bv = b[i] if i < len(b) else 0
        if av < bv:
            return -1
        if av > bv:
            return 1
    return 0


def _parse_spec(spec):
    s = spec.strip()
    if not s:
        return []
    clauses = []
    for clause in s.split(','):
        clause = clause.strip()
        if not clause:
            raise ValueError(f"Invalid spec clause: {clause!r}")
        op = None
        for candidate in _OPERATORS:
            if clause.startswith(candidate):
                op = candidate
                break
        if op is None:
            raise ValueError(f"Invalid spec clause: {clause!r}")
        ver_str = clause[len(op):].strip()
        if not ver_str:
            raise ValueError(f"Invalid spec clause: {clause!r}")
        ver = _parse_version(ver_str)
        if op == '~=':
            if len(ver) < 2:
                raise ValueError(f"Invalid ~= clause: {clause!r}")
            upper = ver[:-1]
            upper[-1] += 1
            clauses.append(('~=', ver, upper))
        else:
            clauses.append((op, ver))
    return clauses


def _eval_clause(clause, ver):
    if clause[0] == '~=':
        _, lower, upper = clause
        return _compare(ver, lower) >= 0 and _compare(ver, upper) < 0
    op, target = clause
    c = _compare(ver, target)
    if op == '==':
        return c == 0
    if op == '!=':
        return c != 0
    if op == '>=':
        return c >= 0
    if op == '<=':
        return c <= 0
    if op == '>':
        return c > 0
    if op == '<':
        return c < 0
    raise ValueError(f"Unknown operator: {op}")


def satisfies(version, spec):
    ver = _parse_version(version)
    for clause in _parse_spec(spec):
        if not _eval_clause(clause, ver):
            return False
    return True


def max_satisfying(versions, spec):
    parsed_versions = []
    for v in versions:
        parsed_versions.append((v, _parse_version(v)))
    clauses = _parse_spec(spec)
    best_str = None
    best_ver = None
    for orig, ver in parsed_versions:
        if not all(_eval_clause(c, ver) for c in clauses):
            continue
        if best_ver is None or _compare(ver, best_ver) > 0:
            best_ver = ver
            best_str = orig
    return best_str
