import re
from collections import deque
from decimal import Decimal, ROUND_HALF_EVEN


class FifoBook:
    _PRICE_RE = re.compile(r'[0-9]+(?:\.[0-9]{1,4})?')
    _CENT = Decimal('0.01')

    def __init__(self):
        self._lots = deque()
        self._position = 0
        self._realized = Decimal('0.00')

    @staticmethod
    def _validate_qty(qty):
        if isinstance(qty, bool) or not isinstance(qty, int):
            raise TypeError('qty must be an int')
        if qty <= 0:
            raise ValueError('qty must be positive')

    @staticmethod
    def _validate_price(price):
        if not isinstance(price, str):
            raise TypeError('price must be a str')
        if not re.fullmatch(FifoBook._PRICE_RE, price):
            raise ValueError('invalid price format')

    def buy(self, qty, price):
        self._validate_qty(qty)
        self._validate_price(price)
        self._lots.append([qty, price, Decimal(price)])
        self._position += qty

    def sell(self, qty, price):
        self._validate_qty(qty)
        self._validate_price(price)
        if qty > self._position:
            raise ValueError('insufficient holdings')

        sell_price = Decimal(price)
        remaining = qty
        pnl = Decimal('0')

        while remaining > 0:
            lot = self._lots[0]
            lot_qty, lot_price_str, lot_price_dec = lot
            consume = lot_qty if remaining >= lot_qty else remaining
            pnl += (sell_price - lot_price_dec) * consume
            if consume == lot_qty:
                self._lots.popleft()
            else:
                lot[0] = lot_qty - consume
            remaining -= consume
            self._position -= consume

        quantized = pnl.quantize(self._CENT, rounding=ROUND_HALF_EVEN)
        self._realized += quantized
        return quantized

    def realized(self):
        return self._realized.quantize(self._CENT, rounding=ROUND_HALF_EVEN)

    def holdings(self):
        return self._position

    def lots(self):
        return [(lot[0], lot[1]) for lot in self._lots]

    def cost_basis(self):
        total = sum(lot[0] * lot[2] for lot in self._lots)
        return total.quantize(self._CENT, rounding=ROUND_HALF_EVEN)
