import copy


def _decode_token(raw):
    out = []
    i = 0
    n = len(raw)
    while i < n:
        ch = raw[i]
        if ch == "~":
            if i + 1 >= n:
                raise ValueError("unescaped ~ at end of token")
            nxt = raw[i + 1]
            if nxt == "0":
                out.append("~")
            elif nxt == "1":
                out.append("/")
            else:
                raise ValueError("invalid escape sequence")
            i += 2
        else:
            out.append(ch)
            i += 1
    return "".join(out)


def _decode_pointer(pointer):
    if pointer == "":
        return []
    if not pointer.startswith("/"):
        raise ValueError("pointer must be empty or start with '/'")
    return [_decode_token(raw) for raw in pointer.split("/")[1:]]


def _read_index(token, length):
    if token == "-":
        raise KeyError(token)
    if not token.isdigit():
        raise KeyError(token)
    if len(token) > 1 and token[0] == "0":
        raise KeyError(token)
    index = int(token)
    if index >= length:
        raise KeyError(token)
    return index


def _write_index(token, length):
    if token == "-":
        return None
    if not token.isdigit():
        raise KeyError(token)
    if len(token) > 1 and token[0] == "0":
        raise KeyError(token)
    index = int(token)
    if index > length:
        raise KeyError(token)
    if index == length:
        return None
    return index


def resolve(doc, pointer):
    tokens = _decode_pointer(pointer)
    current = doc
    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                raise KeyError(token)
            current = current[token]
        elif isinstance(current, list):
            index = _read_index(token, len(current))
            current = current[index]
        else:
            raise KeyError(token)
    return current


def set_value(doc, pointer, value):
    if pointer == "":
        return value
    tokens = _decode_pointer(pointer)
    new_doc = copy.deepcopy(doc)
    parent = new_doc
    for token in tokens[:-1]:
        if isinstance(parent, dict):
            if token not in parent:
                raise KeyError(token)
            parent = parent[token]
        elif isinstance(parent, list):
            index = _read_index(token, len(parent))
            parent = parent[index]
        else:
            raise KeyError(token)
    last = tokens[-1]
    if isinstance(parent, dict):
        parent[last] = copy.deepcopy(value)
    elif isinstance(parent, list):
        index = _write_index(last, len(parent))
        if index is None:
            parent.append(copy.deepcopy(value))
        else:
            parent[index] = copy.deepcopy(value)
    else:
        raise KeyError(last)
    return new_doc


def escape_token(token):
    return token.replace("~", "~0").replace("/", "~1")
