def wrap_text(text, width):
    """Return a list of lines wrapping *text* to *width*.

    Words are ``text.split()``.  Lines are filled greedily.  A word longer
    than *width* is broken into chunks of ``width - 1`` characters followed
    by a hyphen, with the final chunk left unhyphenated.  Empty or
    whitespace-only input returns ``[]``.  Raises ``ValueError`` if *width*
    is not an integer >= 2.
    """
    if not isinstance(width, int) or width < 2:
        raise ValueError("width must be an integer >= 2")

    words = text.split()
    if not words:
        return []

    lines = []
    current = ""
    chunk_size = width - 1

    for word in words:
        word_len = len(word)
        if word_len > width:
            if current:
                lines.append(current)
                current = ""
            i = 0
            while word_len - i > width:
                lines.append(word[i:i + chunk_size] + "-")
                i += chunk_size
            current = word[i:]
        else:
            if current == "":
                current = word
            elif len(current) + 1 + word_len <= width:
                current = current + " " + word
            else:
                lines.append(current)
                current = word

    if current:
        lines.append(current)
    return lines
